package com.bbms.repo;
import com.bbms.domain.*; import org.springframework.data.jpa.repository.JpaRepository; import org.springframework.data.jpa.repository.Lock; import org.springframework.data.jpa.repository.Query; import org.springframework.data.repository.query.Param; import jakarta.persistence.LockModeType; import java.util.*;
public interface DonationRecordRepository extends JpaRepository<DonationRecord,Long>{List<DonationRecord> findAllByOrderByDonationDateDesc(); List<DonationRecord> findByDonorOrderByDonationDateDesc(User donor); Optional<DonationRecord> findByDemoKey(String demoKey); Optional<DonationRecord> findByAppointment(DonationAppointment appointment); boolean existsByAppointment(DonationAppointment appointment); boolean existsByAppointmentAndDonorAndDemoData(DonationAppointment appointment,User donor,boolean demoData); boolean existsByInventoryBatchId(String batchId); @Lock(LockModeType.PESSIMISTIC_WRITE) @Query("select d from DonationRecord d where d.id=:id") Optional<DonationRecord> findByIdForUpdate(@Param("id") Long id); long countByDemoDataTrue(); long count(); long countByDonor(User donor); @Query("select d.appointment.id from DonationRecord d where d.appointment in :appointments and d.donor=:donor and d.demoData=:demoData") Set<Long> findRecordedAppointmentIds(@Param("appointments") Collection<DonationAppointment> appointments,@Param("donor") User donor,@Param("demoData") boolean demoData);}
